          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Network reconnaissance and port scanning",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false
  }
}
